Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
const long long MODX=1000000007,MODY=998244353;
const int maxk=7,base=1000000;
long long limit;
long long counter;
int result;
int prefixSum[maxk];
vector<int> sequences[maxk];

void generate(int x,int depth){
    counter++, sequences[depth].push_back(((counter - x) % MODY + MODY) % MODY);
    prefixSum[depth]=(prefixSum[depth]+sequences[depth].back())%MODX;
    if(depth==6) return;
    for(int d=0; d<=9; d++)
        generate(x*10+d,depth+1);
}

void explore(long long x){
    if(x>limit) return;
    if(x*base+base-1<=limit && x*base*10>limit){
        long long currentOrder=counter;
        for(int i=0,mult=1;i<=6;i++,mult*=10){
            int sz=sequences[i].size();
            int diff=((currentOrder - x*mult) % MODY + MODY) % MODY;
            int pos=lower_bound(sequences[i].begin(),sequences[i].end(),MODY - diff)-sequences[i].begin();
            result=(result+1LL*diff*sz+prefixSum[i])%MODX;
            result=(result-1LL*MODX*(sz - pos)%MODX+MODX)%MODX;
            counter+=sz;
        }
        return;
    }
    counter++, result=(result+((counter - x) % MODY + MODY) % MODY)%MODX;
    for(int d=0; d<=9; d++)
        explore(x*10+d);
}

int main(){
    cin>>limit;
    counter=0; generate(0,0);
    for(int i=0;i<=6;i++) sort(sequences[i].begin(),sequences[i].end());
    counter=0;
    for(int i=1;i<=9;i++) explore(i);
    cout<<result<<endl;
    return 0;
}
</original_code>
